      for (let index = 0; index < this.carried[productId].length; index += 1) {
        const sprite = this.carried[productId][index]!;
        if (index < count) {
          const angleOffset = stackIndex % 2 === 0 ? -5 : 5;
          sprite.setPosition(angleOffset, -43 - stackIndex * 10).setAngle(angleOffset * .7).setVisible(true);
          stackIndex += 1;
        } else sprite.setVisible(false);
      }
    }
    const full = isFullCapacity(stackIndex, state.player.capacity);
    if (full && !this.wasFull) this.fullPulseStartedAt = state.elapsedMs;
    this.wasFull = full;
    if (!full) { this.fullBadge.setVisible(false); return; }
    const marker = fullBadgePlacement(state.player, stackIndex, 540, 960, [{ x: 0, y: 0, width: 540, height: 142 }]);
