    const age = state.elapsedMs - this.fullPulseStartedAt;
    const sample = sampleMotion(createMotionSpec('feedback', prefersReducedMotion()), age);
    this.fullBadge.setScale(1 + Math.sin(sample.progress * Math.PI) * .12).setAlpha(1);
  }
}

let sceneReadyResolve: (() => void) | undefined;
const sceneReady = new Promise<void>((resolve) => { sceneReadyResolve = resolve; });
function markSceneReady(): void { sceneReadyResolve?.(); sceneReadyResolve = undefined; }

function createGame(): void {
  new Phaser.Game({
    type: Phaser.AUTO,
    parent: 'game',
    width: config.world.width,
    height: config.world.height,
    transparent: false,
    backgroundColor: config.palette[2] ?? '#F4D58D',
    render: { antialias: true, pixelArt: false, roundPixels: true },
    scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
    scene: [MarketScene],
  });
}

async function revealShell(): Promise<void> {
  await sceneReady;
  const motionTargets = [...document.querySelectorAll<HTMLElement>('[data-motion]')].filter((element) => element.id !== 'toast');
  await Promise.all(motionTargets.map((element) => animateElement(element, element.dataset.motion === 'panel' ? 'panel' : 'feedback')));
  const loading = document.querySelector<HTMLElement>('#loading-overlay');
  if (!loading) return;
  const spec = createMotionSpec('panel', prefersReducedMotion());
  await runRafMotion(spec, (progress) => {
    loading.style.opacity = String(1 - progress);
    loading.style.transform = `translate3d(0, ${progress * -8}px, 0)`;
  });
  loading.hidden = true;
}

const textureUrls = Object.values(config.assets);
void preloadBeforePlayback(textureUrls, preloadImage, createGame).then(revealShell).catch((error: unknown) => {
  const loading = document.querySelector<HTMLElement>('#loading-overlay');
  if (loading) loading.textContent = `资源加载失败：${error instanceof Error ? error.message : '未知错误'}`;
});

